actions.script:
if (!ec.entity.isEntityDefined('zenith.erp.saas.SaasTenant')) return
def org = scope.organizationPartyId
def kotPlan = ec.entity.find('zenith.erp.saas.SaasTenant')
    .condition('organizationPartyId',org).condition('planId','KOT').disableAuthz().useCache(true).count() > 0
if (!kotPlan) return
// Count across the organization before applying any selected shop or cashier assignment.
def counters = ec.entity.find('zenith.erp.pos.PosTerminal')
    .condition('organizationPartyId',org).condition('isActive','Y')
    .selectField('terminalId').limit(2).disableAuthz().list()
scope.kotCounterId = counters.size() == 1 ? counters[0].terminalId : null
scope.kotCounterConfigured = scope.kotCounterId != null
if (scope.terminalRestricted) scope.allowedTerminalIds = scope.allowedTerminalIds.findAll { it == scope.kotCounterId }
else scope.allowedTerminalIds = scope.kotCounterConfigured ? [scope.kotCounterId] : []
scope.terminalRestricted = true
if (terminalId && !scope.allowedTerminalIds.contains(terminalId)) {
    scope.allowed = false
    ec.message.addError('KOT Plan allows billing at one active counter. Ask your administrator to check the counter setup.')
}

def row=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId).one()
def counter=row ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',row.terminalId).one() : null
def shop=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
def facility=counter?.facilityId ? ec.entity.find('mantle.facility.Facility').condition('facilityId',counter.facilityId).one() : null
if(scope.kotCounterConfigured == false || (scope.kotCounterId && counter?.terminalId != scope.kotCounterId)) {
    ec.message.addError('KOT Plan allows billing at one active counter. Ask your administrator to check the counter setup.'); return
}
if(row?.statusId!='PsOpen' || row.operatorPartyId!=ec.user.userAccount?.partyId || counter?.isActive!='Y' ||
    counter.organizationPartyId!=scope.organizationPartyId || facility?.ownerPartyId!=scope.organizationPartyId || (shop && counter.facilityId!=shop)) {
    ec.message.addError('Choose your open terminal session in this shop.'); return
}
session=row.getMap(); terminal=counter.getMap()

if.script:
def completedBills = {
    def bills = ec.entity.find('zenith.erp.pos.KotTransactionDetailView')
        .condition([kotOrganizationPartyId:scope.organizationPartyId,facilityId:terminal.facilityId,statusId:'PtCompleted'])
    if (scope.terminalRestricted) bills.condition([terminalId:terminal.terminalId,operatorPartyId:session.operatorPartyId])
    return bills.useCache(false)
}
def last = completedBills().condition('sessionId',session.sessionId)
    .selectFields(['transactionNumber','payableAmount']).orderBy('-completedDate,-transactionId').limit(1).list()[0]
def zone = java.time.ZoneId.of('Asia/Kolkata')
def day = ec.user.nowTimestamp.toInstant().atZone(zone).toLocalDate()
def today = {
    completedBills()
        .condition('completedDate',org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO,java.sql.Timestamp.from(day.atStartOfDay(zone).toInstant()))
        .condition('completedDate',org.moqui.entity.EntityCondition.LESS_THAN,java.sql.Timestamp.from(day.plusDays(1).atStartOfDay(zone).toInstant()))
}
billSummary = [lastCompleted:last?.getMap(),
    todayBillCount:today().selectField('transactionId').distinct(true).count(),
    latestIssuedBillNo:today().selectField('transactionNumber')
        .orderBy('-completedDate,-lastUpdatedStamp').limit(1).list()[0]?.transactionNumber ?: '—']

actions.script:
def billing = ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',sessionId).call()
if (!billing?.terminal) return
def org = billing.terminal.organizationPartyId
def ticket = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',kotId)
    .condition('organizationPartyId',org).one()
def tx = ticket?.transactionId ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',ticket.transactionId)
    .condition('organizationPartyId',org).condition('statusId','PtCompleted').one() : null
if (!tx) return
def issuedAt = ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',tx.sessionId)
    .condition('organizationPartyId',org).one()
if (issuedAt?.terminalId != billing.terminal.terminalId || (ticket.terminalId && ticket.terminalId != issuedAt.terminalId)) return
def scope = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',tx.transactionId).call()
if (scope?.allowed) bill = tx.getMap()

def sid=sessionId, kid=kotId
def reject={ String reason -> ec.message.addError(reason) }
if(!sid || !kid) { reject('Choose an open terminal session and a saved order.'); return }
def scope=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameters([sessionId:sid,kotId:kid]).call()
def access=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameter('moduleId',((ec.web?.request?.requestURI ?: '') ==~ /\/(apps|qapps)\/zenith\/kot\/.+/) ? 'kot' : 'pos').call()
if(!scope.allowed || access.canWrite!=true) { reject('You do not have access to bill this order.'); return }
// Checkout and offline replay lock the session before any ticket or table.
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sid).forUpdate(true).one()
def kot=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId',kid).forUpdate(true).one()
def terminal=ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',session?.terminalId).one()
def billing=ec.service.sync().name('zenith.pos.KotServices.get#BillingSession').parameter('sessionId',sid).call()
if(!billing.terminal || ec.message.hasError()) {
    def error = ec.message.errorsString?.trim() ?: 'Choose your open terminal session in this shop.'
    if (!ec.message.hasError()) reject(error)
    return
}
def shop=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
if(!kot || (!kot.terminalId && scope.terminalRestricted) || session?.operatorPartyId!=ec.user.userAccount?.partyId || !terminal || (shop && terminal.facilityId!=shop) || (kot.terminalId && kot.terminalId!=terminal.terminalId)) {
    reject('Choose your terminal session in this shop.'); return
}
if(!kot.transactionId) {
    def fromDraft=kot.statusId=='KotDraft'
    def kitchenActive=['KotNew','KotPreparing','KotReady']
    if(!(kot.statusId in (kitchenActive+['KotDraft','KotServed'])) || !kot.orderReceiptJson || session.statusId!='PsOpen' || terminal.isActive!='Y') {
        reject('This order or terminal session is no longer available for billing.'); return
    }
    def table=kot.tableId ? ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',kot.tableId).forUpdate(true).one() : null
    if(kot.tableId && (!table || table.facilityId!=terminal.facilityId || !(table.statusId in [null,'TblAvailable','TblOccupied']))) {
        reject('Choose an available or occupied table at the terminal shop.'); return
    }
    def quote=new groovy.json.JsonSlurper().parseText(kot.orderReceiptJson)
    if(quote.items.any { it.pricePending == true }) {
        reject('Enter a price above ₹0 for each unpriced product before payment.'); return
    }
    if(confirmedTotal) {
        def amount=confirmedTotal.toString()
        if(!amount.isBigDecimal() || new BigDecimal(amount).compareTo(quote.summary.total as BigDecimal)!=0) {
            reject('The saved order total changed. Reopen it in History and review it before taking payment.'); return
        }
    }
    def tx=ec.service.sync().name('zenith.pos.PosServices.create#PosTransaction')
        .parameters([sessionId:sid,reuseOpenCart:false]).call()?.transactionId
    if(!tx) { reject(ec.message.errorsString ?: 'Could not create the bill.'); return }
    for(def item in quote.items) {
        ec.service.sync().name('zenith.pos.PosServices.add#PosTransactionItem')
            .parameters([transactionId:tx,productId:item.productId,quantity:item.qty,
                salesModeId:quote.bill.salesModeId,taxOn:quote.bill.taxOn,
                unitPrice:item.manualPrice=='Y' ? item.rate : null,manualUnitPrice:item.manualPrice=='Y']).call()
        if(ec.message.hasError()) return
    }
    def current=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',tx).one()
    if((current.payableAmount as BigDecimal).compareTo(quote.summary.total as BigDecimal)!=0) {
        reject('The terminal total changed. Reopen the order to review its prices and tax before taking payment.'); return
    }
    // Attach the customer recorded on the validated order snapshot (never request-supplied here).
    def custPid=quote.bill?.customerPartyId
    if(custPid) ec.service.sync().name('update#zenith.erp.pos.PosTransaction')
        .parameters([transactionId:tx,customerPartyId:custPid,customerName:quote.bill.customer,
            customerPhone:quote.bill.customerPhone,customerTaxRegNumber:quote.bill.customerTaxRegNumber]).call()
    def method=paymentMethod
    if(method=='Credit') {
        ec.service.sync().name('zenith.pos.PosServices.complete#PosTransactionCredit')
            .parameters([transactionId:tx,customerPartyId:custPid ?: creditCustomerPartyId,
                customerName:(custPid && quote.bill.customer) ? quote.bill.customer : customerName,
                customerPhone:(custPid && quote.bill.customerPhone) ? quote.bill.customerPhone : customerPhone,
                upfrontAmount:upfrontAmount,upfrontMethod:upfrontMethod,creditDays:creditDays,termsReason:termsReason,
                attachMissingCustomerPhone:true]).call()
    } else {
        if(!(method in ['Cash','UPI','Card','Split'])) { reject('Choose a valid payment method.'); return }
        def payments=[]
        try {
            if(method=='Split') {
                payments=[['Cash',cashAmount],['Card',cardAmount],['UPI',upiAmount]]
                    .collect { [it[0],new BigDecimal(it[1] ?: '0')] }
            } else {
                payments=[[method,method=='Cash' ? new BigDecimal(cashAmount ?: '0') : current.payableAmount]]
            }
        } catch(Exception ignored) { reject('Enter valid payment amounts.'); return }
        if(payments.any { it[1]<0 || it[1].scale()>2 } || (method=='Split' && payments.count { it[1]>0 }<2)) {
            reject('Enter valid amounts for the selected payment methods.'); return
        }
        for(def payment in payments.findAll { it[1]>0 }) {
            def reference=method=='Split' ? [Card:cardRef,UPI:upiRef][payment[0]] : null
            ec.service.sync().name('zenith.pos.PosServices.process#PosPayment')
                .parameters([transactionId:tx,paymentMethod:payment[0],amount:payment[1],referenceNumber:reference ?: referenceNumber]).call()
            if(ec.message.hasError()) return
        }
        ec.service.sync().name('zenith.pos.PosServices.complete#PosTransaction').parameter('transactionId',tx).call()
    }
    if(ec.message.hasError()) return
    kot.setAll([transactionId:tx,terminalId:terminal.terminalId])
    if(fromDraft) {
        def display=ec.service.sync().name('zenith.pos.KotServices.get#KitchenDisplayPolicy').parameter('facilityId',terminal.facilityId).call()
        kot.setAll([statusId:display.enabled ? 'KotNew' : 'KotServed',kotDate:ec.user.nowTimestamp])
    }
    kot.update()
    if(table) {
        def cf=ec.entity.conditionFactory
        def openTickets=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',scope.organizationPartyId)
            .condition('tableId',table.tableId).condition('kotId','!=',kid)
            .condition(cf.makeCondition([
                cf.makeCondition('statusId',org.moqui.entity.EntityCondition.IN,kitchenActive),
                cf.makeCondition([statusId:'KotDraft',transactionId:null]),
                cf.makeCondition([statusId:'KotServed',transactionId:null])
            ],org.moqui.entity.EntityCondition.OR)).count()
        if(kot.statusId in kitchenActive || openTickets || table.currentTransactionId) table.set('statusId','TblOccupied').update()
        else table.set('statusId','TblAvailable').update()
    }
}
def billScope=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',kot.transactionId).call()
def bill=billScope.allowed ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',kot.transactionId)
    .condition('sessionId',sid).condition('statusId','PtCompleted').one() : null
if(!bill) { reject('This order was already billed on another session.'); return }
if (confirmedTax != null && confirmedTax.compareTo((bill.totalTaxAmount ?: 0) as BigDecimal) != 0) {
    reject('The terminal tax changed. Review this order before syncing payment.'); return
}
checkout=[success:true,kotId:kid,transactionId:bill.transactionId,billNumber:bill.transactionNumber,changeAmount:bill.changeAmount ?: 0G]

def uri = ec.web?.request?.requestURI ?: ''
def moduleId = uri ==~ /\/(apps|qapps)\/zenith\/kot\/.+/ ? 'kot' : 'pos'
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', moduleId).call()
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (access?.canWrite != true || !org || org == '_NA_') {
    ec.message.addError('Write access and an active shop are required for this kitchen workflow.')
    return
}
def key = 'KOT_' + org
def counter = ec.entity.find('zenith.erp.pos.PosBillSequence').condition('seqKey', key).forUpdate(true).one()
int nextNum
if (counter) {
    nextNum = ((counter.lastNumber ?: 1000) as int) + 1
    counter.set('lastNumber', nextNum).update()
} else {
    int maxNum = 1000
    def prior = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
        .condition('organizationPartyId', org).selectField('kotNumber').list()
    prior.each { row ->
        def n = row.kotNumber?.toString()
        if (n ==~ /\d+/) maxNum = Math.max(maxNum, n.toInteger())
    }
    nextNum = maxNum + 1
    try {
        ec.service.sync().name('create#zenith.erp.pos.PosBillSequence')
            .parameters([seqKey:key, lastNumber:nextNum]).call()
    } catch (Exception ignored) {
        def current = ec.entity.find('zenith.erp.pos.PosBillSequence')
            .condition('seqKey', key).forUpdate(true).one()
        nextNum = ((current.lastNumber ?: maxNum) as int) + 1
        current.set('lastNumber', nextNum).update()
    }
}
kotNumber = String.valueOf(nextNum)

table = null
if (tableId) {
    def row = tableId.toString().contains('*') ? null : ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',tableId).forUpdate(true).one()
    def facility = row ? ec.entity.find('mantle.facility.Facility').condition('facilityId',row.facilityId).one() : null
    if (!row || facility?.ownerPartyId != scope.organizationPartyId) { ec.message.addError('Select a table in this shop.'); return }
    table = row.getMap()
} else if (tableNumber) {
    def facilities=ec.entity.find('mantle.facility.Facility').condition('ownerPartyId',scope.organizationPartyId).list()*.facilityId
    def matches=facilities ? ec.entity.find('zenith.erp.pos.RestaurantTable').condition('facilityId','in',facilities).condition('tableNumber',tableNumber).forUpdate(true).list() : []
    if(matches.size()>1) { ec.message.addError('Select the table and its facility; this number exists in more than one facility.'); return }
    if(matches) table=matches[0].getMap()
}

def uri = ec.web?.request?.requestURI ?: ''
def moduleId = uri ==~ /\/(apps|qapps)\/zenith\/kot\/.+/ ? 'kot' : 'pos'
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', moduleId).call()
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (access?.canWrite != true || !org || org == '_NA_') {
    ec.message.addError('Write access and an active shop are required for this kitchen workflow.')
    return
}
def kot = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
    .condition('kotId', kotId).forUpdate(true).one()
if (!kot || kot.organizationPartyId != org) {
    ec.message.addError('Kitchen order not found in this shop.')
    return
}
def allowed = [KotNew:['KotPreparing', 'KotCancelled'],
               KotPreparing:['KotReady', 'KotCancelled'],
               KotReady:['KotServed']]
if (!(statusId in (allowed[kot.statusId] ?: []))) {
    ec.message.addError('This kitchen order can no longer move to that status. Refresh the page.')
    return
}
kot.set('statusId', statusId).update()
// A served order can release the table only after its bill is completed.
if (kot.tableId && statusId in ['KotCancelled','KotServed']) {
    def billed = statusId=='KotServed' && kot.transactionId &&
        ec.entity.find('zenith.erp.pos.PosTransaction').condition([transactionId:kot.transactionId,
            organizationPartyId:org,statusId:'PtCompleted']).count()
    if (statusId=='KotServed' && !billed) return
    def table=ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',kot.tableId).forUpdate(true).one()
    def facility=table ? ec.entity.find('mantle.facility.Facility').condition('facilityId',table.facilityId).one() : null
    def active=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',org)
        .condition('tableId',kot.tableId).condition('statusId','in',['KotNew','KotPreparing','KotReady']).count()
    if (billed && !active) active=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',org)
        .condition('tableId',kot.tableId).condition('transactionId',null).condition('statusId','in',['KotDraft','KotServed']).count()
    if (facility?.ownerPartyId==org && !active && !table.currentTransactionId && table.statusId=='TblOccupied') table.set('statusId','TblAvailable').update()
}

def uri = ec.web?.request?.requestURI ?: ''
def moduleId = uri ==~ /\/(apps|qapps)\/zenith\/kot\/.+/ ? 'kot' : 'pos'
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', moduleId).call()
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (access?.canWrite != true || !org || org == '_NA_') {
    ec.message.addError('Write access and an active shop are required for this kitchen workflow.')
    return
}
def kot = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
    .condition('kotId', kotId).forUpdate(true).one()
if (!kot || kot.organizationPartyId != org) {
    ec.message.addError('Kitchen order not found in this shop.')
    return
}
printCount=((kot.printCount ?: 0) as int)+1
kot.set('printCount',printCount).update()
